import {uid,uuid,validUUID,parseText,parseBtsnoop,byteDiff,keyFor,validateCommand,mapping,sampleSession,normalize,MAX_EVENTS,runtimeProfile} from './core.mjs';
import './transports.mjs';
window.addEventListener('ble-browser-capture',e=>importResult({observations:e.detail.observations,warnings:['Web Bluetooth capture records this browser’s own connection only.']},e.detail.name));
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),short=s=>s?(s.length>12?s.slice(0,8)+'…'+s.slice(-4):s):'Unresolved';
const KEY='blueshark-v2';let workspace={version:2,sessions:[sampleSession()]},active,page='capture',selected='',search='',direction='all',connection='',charFilter='',diffA='',diffB='',format='json';
try{const data=JSON.parse(localStorage.getItem(KEY));if(data?.version===2&&data.sessions?.length)workspace=data;document.documentElement.classList.toggle('dark',localStorage.getItem('ble-theme')==='dark');}catch{}
active=workspace.sessions[0].id;const current=()=>workspace.sessions.find(s=>s.id===active);
function toast(text){$('toast').textContent=text;$('toast').className='visible';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').className='',4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(workspace));$('saved').textContent='Saved on this browser';}catch{$('saved').textContent='Not saved • storage unavailable';toast('Download a backup before leaving: browser storage is unavailable or full.');}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reset(){selected='';search='';direction='all';connection='';charFilter='';diffA='';diffB='';}
function render(){const s=current();$('session').innerHTML=workspace.sessions.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('session').value=active;$('title').textContent={capture:'Capture',inspect:'Inspect & map',export:'Integration'}[page];document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$('banner').hidden=!s.synthetic;$('banner').textContent='Demo session • Fictional data. Explore freely; synthetic sessions cannot produce executable commands.';$('content').innerHTML=page==='capture'?captureHTML():page==='inspect'?inspectHTML():exportHTML();if(page==='capture')bindCapture();if(page==='inspect')bindInspect();if(page==='export')bindExport();}
const example='[0.000] WRITE_CMD action="Power on" service=fff0 char=fff1 value=01 01\n[0.065] NOTIFY action="Power on" service=fff0 char=fff2 value=A1 01';
function captureHTML(){const s=current();return `<div class="grid"><section class="card"><h2>Bring in a capture</h2><p class="muted">Imports create separate sessions. Your previous captures and demo data stay untouched.</p><label id="drop" class="drop"><strong>Drop a capture or choose a file</strong><small>JSON · CSV · TXT · LOG · BTSNOOP · up to 10 MB</small><input id="file" type="file" accept=".json,.csv,.txt,.log,.btsnoop,.cfa"></label><label>Paste observations<textarea id="capture-input" rows="7" spellcheck="false" placeholder="${esc(example)}"></textarea></label><div class="actions" style="margin-top:12px"><button id="parse" class="primary">Import capture</button><button id="example">Fill sample</button></div><p id="import-error" class="error" role="alert"></p><details><summary>Formats & field reference</summary><p class="muted">JSON array or {observations: [...]}, header-based CSV/TSV, or key=value lines. Required: direction and value. UUIDs can be supplied later. Invalid text rows reject the entire import.</p><pre>${esc(example)}</pre><p class="muted">Optional: action, timestamp, service, characteristic, connection, handle (0x0025), response (true/false). write_cmd means without-response; write_req means with-response. Wireshark CSV accepts btatt.opcode, btatt.handle, btatt.value, bthci_acl.chandle and frame.time_relative. Raw PCAP/PCAPNG must first be exported as GATT CSV.</p></details><details><summary>Restore workspace backup</summary><p class="muted">Adds backed-up sessions without replacing your current sessions.</p><input id="restore" type="file" accept=".json" aria-label="Restore workspace"></details></section><div><section class="card"><h2>From capture to integration</h2>${[['Capture one action','Start idle, press one button, wait, and repeat. Record timestamps.'],['Inspect the evidence','Label events, resolve UUIDs and compare bytes across repeated actions.'],['Review before exporting','Record physical-device test evidence. Only eligible fixed-payload commands become buttons.']].map((x,i)=>`<div class="step"><b>${i+1}</b><div><strong>${x[0]}</strong><p>${x[1]}</p></div></div>`).join('')}<button id="open-guide">Open guided capture</button></section><section class="card"><h2>${esc(s.name)}</h2><div class="stats"><div><strong>${s.observations.length}</strong><span>events</span></div><div><strong>${new Set(s.observations.map(e=>e.action)).size}</strong><span>actions</span></div><div><strong>${s.commands.length}</strong><span>mappings</span></div></div><button class="primary" id="inspect">Inspect session</button>${s.warnings.map(w=>`<p class="muted">${esc(w)}</p>`).join('')}</section></div></div>`;}
function importResult(result,name){const s={id:uid(),name,synthetic:result.observations.some(e=>e.synthetic),device:{name,manufacturer:'',model:'',address:''},observations:result.observations,catalog:[],commands:[],warnings:result.warnings,created_at:new Date().toISOString()};workspace.sessions.push(s);active=s.id;reset();save();page='inspect';render();toast(`${s.observations.length} events imported into a separate session.`);}
async function importFile(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('Capture exceeds 10 MB; split it first.');const buffer=await file.arrayBuffer(),magic=new TextDecoder().decode(buffer.slice(0,8));importResult(magic==='btsnoop\0'?parseBtsnoop(buffer):parseText(new TextDecoder().decode(buffer)),file.name);}catch(e){$('import-error').textContent=e.message;}}
function bindCapture(){$('parse').onclick=()=>{try{importResult(parseText($('capture-input').value),'Capture '+new Date().toLocaleTimeString());}catch(e){$('import-error').textContent=e.message;}};$('example').onclick=()=>{$('capture-input').value=JSON.stringify({observations:parseText(example).observations.map(e=>({...e,synthetic:true}))},null,2);};$('file').onchange=e=>importFile(e.target.files[0]);$('drop').ondragover=e=>e.preventDefault();$('drop').ondrop=e=>{e.preventDefault();importFile(e.dataTransfer.files[0]);};$('open-guide').onclick=openGuide;$('inspect').onclick=()=>{page='inspect';render();};$('restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('Backup exceeds 10 MB.');const data=JSON.parse(await f.text());if(data.version!==2||!Array.isArray(data.sessions)||data.sessions.length>50)throw Error('Not a valid version 2 workspace backup.');const restored=data.sessions.map(s=>{if(!Array.isArray(s.observations)||s.observations.length>MAX_EVENTS||!Array.isArray(s.commands)||!s.device)throw Error('Invalid session.');const events=s.observations.map((r,i)=>({...normalize(r,i),id:String(r.id||uid())}));const commands=s.commands.map(c=>{const n=normalize({...c,direction:'write'});if(!['observed','hypothesis','tested'].includes(c.stage)||typeof c.notes!=='string')throw Error('Invalid command review.');return {...n,id:uid(),name:String(c.name||''),stage:c.stage,notes:c.notes,entity:'button'};});return {id:uid(),name:String(s.name||'Restored'),synthetic:s.synthetic===true||events.some(r=>r.synthetic),device:{name:String(s.device.name||'Device'),manufacturer:String(s.device.manufacturer||''),model:String(s.device.model||''),address:String(s.device.address||'')},observations:events,commands,catalog:Array.isArray(s.catalog)?s.catalog:[],warnings:['Restored: recheck evidence before installing.'],created_at:new Date().toISOString()};});workspace.sessions.push(...restored);save();render();toast(`Restored ${restored.length} sessions.`);}catch(e){toast(e.message);}};}
function filtered(){return current().observations.filter(e=>(direction==='all'||e.direction===direction)&&(!connection||e.connection===connection)&&(!charFilter||(e.characteristic||e.handle)===charFilter)&&`${e.action} ${e.value} ${e.characteristic} ${e.service}`.toLowerCase().includes(search.toLowerCase()));}
const options=events=>events.map(e=>`<option value="${esc(e.id)}">${esc(e.action)} · ${e.direction} · ${esc(e.value)} · ${esc(e.timestamp)}</option>`).join('');
function inspectHTML(){const s=current(),events=filtered(),sel=s.observations.find(e=>e.id===selected),connections=[...new Set(s.observations.map(e=>e.connection).filter(Boolean))],gatt=[...new Map(s.observations.map(e=>[`${e.connection}|${e.characteristic||e.handle}`,e])).values()];return `<div class="grid"><div><section class="card"><div class="heading"><h2>Observations</h2><span class="badge">${events.length} / ${s.observations.length} events</span></div><div class="filters"><label>Search<input id="search" value="${esc(search)}" placeholder="Action, UUID or bytes"></label><label>Operation<select id="direction">${['all','write','notify','indicate','read'].map(d=>`<option ${d===direction?'selected':''}>${d}</option>`).join('')}</select></label><label>Connection<select id="connection"><option value="">All</option>${connections.map(c=>`<option ${c===connection?'selected':''}>${esc(c)}</option>`).join('')}</select></label><button id="reset">Reset</button></div><div class="table"><table><thead><tr><th>Time / action</th><th>Operation</th><th>Characteristic</th><th>Payload</th><th></th></tr></thead><tbody>${events.slice(0,250).map(e=>`<tr class="${selected===e.id?'selected':''}"><td><small>${esc(e.timestamp||'No timestamp')}</small><br>${esc(e.action)}</td><td><span class="tag">${e.direction}</span></td><td><code title="${esc(e.characteristic)}">${esc(short(e.characteristic))}</code>${!e.characteristic?`<br><small>${esc(e.handle||'No handle')}</small>`:''}</td><td><code>${esc(e.value)}</code></td><td><button class="select-event" data-id="${esc(e.id)}">Inspect</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching events. Import a capture or reset the filters.</td></tr>'}</tbody></table></div>${events.length>250?'<p class="muted">First 250 matches shown. Narrow filters; exports retain every event.</p>':''}<div class="actions" style="margin-top:14px"><input id="label" placeholder="Label filtered events…" aria-label="Action label" style="flex:1"><button id="label-apply">Apply (${events.length})</button></div><p class="muted">Filter to the intended events first. Matching labels or close timestamps are not proof of causality.</p></section><section class="card"><h2>Byte comparison</h2><p class="muted">Choose write or notification variants. Changed positions are highlighted; semantics are not guessed.</p><div class="fields"><label>Baseline<select id="diff-a"><option value="">Select event</option>${options(s.observations.slice(0,1000))}</select></label><label>Comparison<select id="diff-b"><option value="">Select event</option>${options(s.observations.slice(0,1000))}</select></label></div><div id="diff-result" class="muted">Choose two events to compare.</div></section></div><div><section class="card"><h2>GATT structure</h2><div class="gatt">${gatt.map(e=>`<button class="gatt-filter ${charFilter===(e.characteristic||e.handle)?'active':''}" data-char="${esc(e.characteristic||e.handle)}"><strong>${esc(short(e.characteristic))} ${!e.characteristic?esc(e.handle):''}</strong><small>Service ${esc(short(e.service))} · ${esc(e.connection||'Connection unspecified')}</small></button>`).join('')||'<p class="muted">No GATT evidence yet.</p>'}</div></section><section class="card">${sel?inspectorHTML(sel):'<h2>Inspect an event</h2><p class="muted">Select Inspect beside an observation to label it, resolve UUIDs or map a write command.</p>'}</section></div></div>`;}
function inspectorHTML(e){const c=current().commands.find(c=>c.key===keyFor(e));return `<h2>${e.direction==='write'?'Map a command':'Inspect event'}</h2><p><code>${esc(e.value)}</code></p><form id="event-form"><label>Button action<input id="action" required maxlength="120" value="${esc(e.action)}"></label><details ${!e.characteristic?'open':''}><summary>Resolve GATT identifiers</summary><p class="muted">Copy UUIDs from discovery for this connection. Handles are not UUIDs. Updating a handle applies only to this captured connection.</p><div class="fields"><label class="wide">Service UUID<input id="service" value="${esc(e.service)}"></label><label class="wide">Characteristic UUID<input id="characteristic" value="${esc(e.characteristic)}"></label></div></details><button type="submit" style="margin-top:12px">Save event / UUID mapping</button></form>${e.direction==='write'?`<details open><summary>Command review</summary><form id="command-form"><div class="fields"><label class="wide">Command name<input id="command-name" required value="${esc(c?.name||e.action)}"></label><label>Write mode<select id="response"><option value="unknown">Unknown</option><option value="true">With response</option><option value="false">Without response</option></select></label><label>Evidence stage<select id="stage"><option value="observed">Observed</option><option value="hypothesis">Hypothesis</option><option value="tested">Device-tested (your report)</option></select></label><label class="wide">Evidence / test notes<textarea id="notes" rows="4" placeholder="Record firmware, effects, repeat count and test conditions.">${esc(c?.notes||'')}</textarea></label></div><p class="muted">One button for this exact payload. Mark tested only after a physical-device test. This workbench does not test or send commands.</p><button type="submit" class="primary">Save command mapping</button></form></details>`:''}<details><summary>Raw evidence</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details>`;}
function bindInspect(){$('search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);};$('direction').onchange=e=>{direction=e.target.value;render();};$('connection').onchange=e=>{connection=e.target.value;render();};$('reset').onclick=()=>{reset();render();};document.querySelectorAll('.gatt-filter').forEach(b=>b.onclick=()=>{charFilter=charFilter===b.dataset.char?'':b.dataset.char;render();});document.querySelectorAll('.select-event').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render();});$('label-apply').onclick=()=>{const name=$('label').value.trim(),events=filtered();if(!name)return;events.forEach(e=>e.action=name);save();render();toast(`Labeled ${events.length} events.`);};$('diff-a').value=diffA;$('diff-b').value=diffB;function diff(){const a=current().observations.find(e=>e.id===diffA),b=current().observations.find(e=>e.id===diffB);if(!a||!b)return;const bytes=byteDiff(a.value,b.value);$('diff-result').innerHTML=`<span class="badge">${bytes.filter(x=>x.changed).length} changed / ${bytes.length} positions</span><div class="diff">${bytes.map(x=>`<div class="byte ${x.changed?'changed':''}"><small>+${x.offset}</small><code>${x.a}</code><code>${x.b}</code><small>${x.decimal??'—'} / ${esc(x.ascii)}</small></div>`).join('')}</div><small>Offset · baseline hex · comparison hex · decimal / ASCII</small>`;}$('diff-a').onchange=e=>{diffA=e.target.value;diff();};$('diff-b').onchange=e=>{diffB=e.target.value;diff();};diff();const e=current().observations.find(e=>e.id===selected);if(!e)return;$('event-form').onsubmit=event=>{event.preventDefault();const service=uuid($('service').value),characteristic=uuid($('characteristic').value);if((service&&!validUUID(service))||(characteristic&&!validUUID(characteristic)))return toast('Invalid UUID. Use 16-bit, 32-bit or full 128-bit form.');e.action=$('action').value.trim();const matches=e.handle?current().observations.filter(x=>x.handle===e.handle&&x.connection===e.connection):[e];matches.forEach(x=>{x.service=service;x.characteristic=characteristic;});current().catalog.push({connection:e.connection,handle:e.handle,service,characteristic,provenance:'User-supplied discovery mapping'});save();render();toast('Event saved. Previously saved commands retain their own review evidence.');};if(e.direction==='write'){const c=current().commands.find(x=>x.key===keyFor(e));$('response').value=String(c?.response??e.response??'unknown');$('stage').value=c?.stage||'observed';$('command-form').onsubmit=event=>{event.preventDefault();const r=$('response').value,cmd={...e,id:c?.id||uid(),key:keyFor(e),name:$('command-name').value.trim(),response:r==='unknown'?null:r==='true',stage:$('stage').value,notes:$('notes').value.trim(),entity:'button',evidence_ids:[e.id]};if(cmd.stage==='tested'&&!cmd.notes)return toast('Record physical-device test evidence first.');const i=current().commands.findIndex(x=>x.id===cmd.id);if(i<0)current().commands.push(cmd);else current().commands[i]=cmd;save();render();toast('Mapping saved. Integration tab shows eligibility.');};}}
function exportText(){const s=current();if(format==='json')return JSON.stringify(mapping(s),null,2);return '# Eligible fixed-payload commands; physical tests are user-reported.\n# Importing this file does not transmit anything.\nCOMMANDS = [\n'+s.commands.filter(c=>!validateCommand(c,s).length).map(c=>'    {"id": '+JSON.stringify(c.id)+', "name": '+JSON.stringify(c.name)+',\n     "service_uuid": '+JSON.stringify(c.service)+',\n     "characteristic_uuid": '+JSON.stringify(c.characteristic)+',\n     "payload": bytes.fromhex('+JSON.stringify(c.value)+'), "response": '+(c.response?'True':'False')+'},').join('\n')+'\n]\n';}
function exportHTML(){const s=current(),ready=s.commands.filter(c=>!validateCommand(c,s).length);return `<div class="grid"><div><section class="card"><h2>Device profile</h2><form id="device-form"><div class="fields"><label>Name<input id="device-name" required value="${esc(s.device.name)}"></label><label>Bluetooth address<input id="address" value="${esc(s.device.address)}" placeholder="Set during Home Assistant setup"></label><label>Manufacturer<input id="maker" value="${esc(s.device.manufacturer)}"></label><label>Model / firmware<input id="model" value="${esc(s.device.model)}"></label></div><button type="submit">Save device details</button></form></section><section class="card"><div class="heading"><h2>Reviewed commands</h2><span class="badge">${ready.length} eligible</span></div><p class="muted">Eligibility is a safety gate, not a compatibility certification. This release creates fixed-payload button entities only.</p>${s.commands.map(c=>{const errors=validateCommand(c,s);return `<article class="command"><div class="heading"><strong>${esc(c.name)}</strong><button class="remove danger" data-id="${esc(c.id)}">Remove</button></div><code>${esc(c.value)}</code><p>${esc(c.notes||'No evidence recorded.')}</p><span class="badge ${errors.length?'warning':''}">${errors.length?esc(errors.join(' · ')):'Eligible • user-reported device test'}</span></article>`;}).join('')||'<div class="empty">No commands mapped.<br>Inspect a write and save its name, mode and evidence.</div>'}</section></div><div><section class="card"><h2>Export for Home Assistant</h2><div class="actions"><button data-format="json">Profile JSON</button><button data-format="python">Python constants</button></div><pre id="export-code">${esc(exportText())}</pre><div class="actions"><button class="primary" id="download">Download ${format==='json'?'profile':'constants'}</button><button id="copy">Copy</button><button id="runtime-download">Download HA install profile</button></div><p class="muted">Profile JSON preserves all observations and blockers. Python includes eligible commands only. HA install profile exports the exact eligible-only runtime schema; set the Bluetooth address first. Keep real captures out of public repositories.</p></section><section class="card"><h2>Home Assistant connection</h2><p><a href="blueshark-source.zip" download>Download complete project source</a> · <a href="README.md" target="_blank">Read installation guide</a></p><p class="notice warning">Not connected. This page has not installed anything in Home Assistant and cannot control a Bluetooth adapter or proxy.</p><p>The custom integration uses Home Assistant’s shared Bluetooth stack: an active ESPHome proxy or a local adapter can provide the connection. No independent scanner is needed.</p><ol><li>Install <strong>BlueShark Integration</strong> from the project README. The optional Workbench add-on hosts this analysis UI; it is not a second Bluetooth gateway.</li><li>Export a profile. Add the integration in Home Assistant and supply the profile and target Bluetooth address.</li><li>Review the buttons and explicitly enable writes. Buttons begin disabled; unknown or synthetic commands remain blocked.</li></ol><p class="muted">Live vendor-app sniffing, automatic installation, state decoders, pairing/key handling and universal device support are not implemented. Proxies do not capture phone-to-device radio traffic.</p><a href="https://developers.home-assistant.io/docs/core/bluetooth/api/" target="_blank" rel="noreferrer">Home Assistant Bluetooth API documentation ↗</a></section></div></div>`;}
function bindExport(){$('runtime-download').onclick=()=>{try{download('blueshark-install.json',JSON.stringify(runtimeProfile(current()),null,2));}catch(e){toast(e.message);}};$('device-form').onsubmit=e=>{e.preventDefault();current().device={name:$('device-name').value.trim(),address:$('address').value.trim(),manufacturer:$('maker').value.trim(),model:$('model').value.trim()};save();render();};document.querySelectorAll('[data-format]').forEach(b=>{b.classList.toggle('primary',b.dataset.format===format);b.onclick=()=>{format=b.dataset.format;render();};});document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{if(!confirm('Remove this mapping? Captured observations remain.'))return;current().commands=current().commands.filter(c=>c.id!==b.dataset.id);save();render();});$('download').onclick=()=>download('blueshark-profile.'+(format==='json'?'json':'py'),exportText(),format==='json'?'application/json':'text/x-python');$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(exportText());toast('Copied.');}catch{toast('Clipboard unavailable. Use Download instead.');}};}
function openGuide(){$('help').showModal();guide();}function guide(){const method=$('method').value;$('guide-content').innerHTML=method==='android'?`<ol><li>Enable Android Developer options and <strong>Bluetooth HCI snoop log</strong>, then restart Bluetooth.</li><li>Open the vendor app, connect your device, record idle traffic, then press one button at a time. Note timestamps and repeat actions.</li><li>Retrieve the btsnoop file through the phone’s supported log/bug-report workflow. Location varies by manufacturer. Do not share the whole bug report; it contains unrelated private data.</li><li>Import the file here. Select the target connection, label actions, and resolve handles using discovery evidence from that connection.</li><li>Disable HCI logging when done.</li></ol><a href="https://source.android.com/docs/core/connect/bluetooth/verifying_debugging" target="_blank" rel="noreferrer">Official Android HCI logging instructions ↗</a><p class="muted">Parser supports H4 btsnoop fixed ATT writes, notifications and indications. EATT, prepared/signed writes and application encryption are not decoded.</p>`:method==='gatt'?`<ol><li>Use a GATT inspection tool with your device. Record service and characteristic UUIDs, properties and handles.</li><li>Export operation, value, timestamp and action as JSON, CSV or key=value text.</li><li>For Wireshark, export selected GATT fields to CSV with connection and handle. Resolve UUIDs from discovery before export.</li><li>Import and compare repeated actions here. This browser never captures another app’s traffic itself.</li></ol>`:`<p>There is no generic browser permission for inspecting another app’s Bluetooth traffic. iOS capture depends on supported Apple diagnostic tools and device access. Over-the-air capture needs compatible sniffer hardware and may not expose encrypted payloads.</p><p>Export decoded GATT events to CSV/JSON. Raw PCAP is not decoded here. No rooting, authentication bypass or key extraction is provided.</p>`;}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});$('session').onchange=e=>{active=e.target.value;reset();render();};$('new').onclick=()=>{const name=prompt('Name this device session','My Bluetooth device');if(!name?.trim())return;importResult({observations:[],warnings:[]},name.trim());page='capture';render();};$('demo').onclick=()=>{const existing=workspace.sessions.find(s=>s.synthetic);if(existing)active=existing.id;else{const s=sampleSession();workspace.sessions.push(s);active=s.id;}reset();save();render();};$('delete').onclick=()=>{if(!confirm('Delete this session and mappings from this browser? Download a backup first if needed.'))return;workspace.sessions=workspace.sessions.filter(s=>s.id!==active);if(!workspace.sessions.length)workspace.sessions.push(sampleSession());active=workspace.sessions[0].id;reset();save();render();};$('backup').onclick=()=>download('blueshark-workspace.json',JSON.stringify(workspace,null,2));$('guide').onclick=openGuide;$('close').onclick=()=>$('help').close();$('method').onchange=guide;$('theme').onclick=()=>{document.documentElement.classList.toggle('dark');try{localStorage.setItem('ble-theme',document.documentElement.classList.contains('dark')?'dark':'light');}catch{}};render();
